import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/rocks-and-geology/","title":"CH1.2 岩石、火山与地质作用 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.2 岩石、火山与地质作用","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/rocks-and-geology/"},"readingTime":{"minutes":35.36,"words":10609},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/2.rocks-and-geology.md","headers":[],"bulletin":false}`),a={name:`2.rocks-and-geology.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="volcano" tabindex="-1"><a class="header-anchor" href="#volcano"><span>Volcano</span></a></h2><p class="vc-meta"><strong>/vɒlˈkeɪnəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>火山</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an active volcano</td><td>活火山</td></tr><tr><td>a dormant volcano</td><td>休眠火山</td></tr><tr><td>an extinct volcano</td><td>死火山</td></tr><tr><td>a volcanic eruption</td><td>火山喷发</td></tr><tr><td>volcanic ash</td><td>火山灰</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the chain of volcanoes along the boundary between two tectonic plates.</p><blockquote><p>该地图显示了两大板块交界处沿线的火山链。</p></blockquote><p><strong>Writing Task 2</strong> Volcanic ash can ground flights across an entire continent for days.</p><blockquote><p>火山灰能让整个大陆的航班停飞数日。</p></blockquote><p><strong>Speaking</strong> We hiked up a dormant volcano — the crater was completely full of cloud.</p><blockquote><p>我们爬上一座休眠火山，火山口里全是云。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>crater</td><td>火山口</td><td>火山顶部的凹陷，不是山体</td></tr><tr><td>magma</td><td>岩浆</td><td>地下的熔融岩石</td></tr><tr><td>geyser</td><td>间歇泉</td><td>地热活动的另一种表现</td></tr><tr><td>volcanic</td><td>火山的</td><td>形容词，作定语用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 罗马神话 <em>Vulcan</em>（火神）→ 意大利语 <em>Volcano</em>（埃奥利群岛中的一座火山岛）</li><li><strong>Family:</strong> volcanic 火山的 / volcanology 火山学 / volcanologist 火山学家</li><li><strong>Memory Tip:</strong> 古人认为火神的作坊就在那座岛的火山里，于是岛名成了通名——和 magnet 来自地名 Magnesia 是同一个套路。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 volcano(e)s 两种拼法都可用。</li><li>作定语要用形容词：volcanic eruption，不是 <s>volcano eruption</s>。</li><li>可数：an active volcano、three volcanoes。</li></ul></div><div class="vocab-card"><h2 id="erupt" tabindex="-1"><a class="header-anchor" href="#erupt"><span>Erupt</span></a></h2><p class="vc-meta"><strong>/ɪˈrʌpt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（火山）喷发；（情绪、暴力、笑声）突然爆发</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the volcano erupted</td><td>火山喷发</td></tr><tr><td>erupt violently</td><td>猛烈喷发</td></tr><tr><td>erupt into violence</td><td>爆发为暴力</td></tr><tr><td>erupt in laughter</td><td>哄堂大笑</td></tr><tr><td>newly erupted lava</td><td>新喷出的熔岩</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how often the volcano erupted between 1800 and 2020.</p><blockquote><p>该图显示了 1800 至 2020 年间该火山喷发的频次。</p></blockquote><p><strong>Writing Task 2</strong> When the volcano erupted in 2010, ash shut down air traffic across Europe for a week.</p><blockquote><p>2010 年该火山喷发时，火山灰使欧洲航空瘫痪了一周。</p></blockquote><p><strong>Speaking</strong> The whole class erupted in laughter when the teacher&#39;s phone rang.</p><blockquote><p>老师的手机一响，全班哄堂大笑。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>explode</td><td>爆炸</td><td>强调瞬间的爆裂，不限于火山</td></tr><tr><td>burst</td><td>迸发</td><td>多用于情感、管道</td></tr><tr><td>spew</td><td>喷出</td><td>强调大量喷涌，含负面色彩</td></tr><tr><td>break out</td><td>爆发</td><td>用于战争、火灾、疾病</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> e-（向外）+ rupt（断裂，拉丁语 <em>rumpere</em>）→ &quot;向外冲破&quot;</li><li><strong>Family:</strong> rupture 断裂 / interrupt 打断 / corrupt 腐败 / bankrupt 破产 / abrupt 突然的</li><li><strong>Memory Tip:</strong> rupt 就是&quot;断&quot;：interrupt 从中间打断、rupture 断裂、bankrupt 是&quot;柜台被砸破&quot;所以破产。e- 朝外，于是 erupt = 向外冲破。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不及物动词：the volcano erupted ✔ / <s>erupted the volcano</s> ✘。</li><li>表&quot;爆发为……&quot;用 erupt into + 名词：erupt into violence。</li><li>拼写 erupt，不是 <s>irrupt</s>（后者指&quot;突然闯入&quot;）。</li></ul></div><div class="vocab-card"><h2 id="magma" tabindex="-1"><a class="header-anchor" href="#magma"><span>Magma</span></a></h2><p class="vc-meta"><strong>/ˈmæɡmə/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>岩浆（地下熔融状态的岩石）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>molten magma</td><td>熔融岩浆</td></tr><tr><td>a magma chamber</td><td>岩浆房</td></tr><tr><td>magma rises to the surface</td><td>岩浆上升至地表</td></tr><tr><td>basaltic magma</td><td>玄武质岩浆</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows magma rising through a vent and cooling into new crust at a mid-ocean ridge.</p><blockquote><p>该图显示了岩浆沿通道上升，并在洋中脊冷却形成新地壳的过程。</p></blockquote><p><strong>Writing Task 2</strong> Geothermal plants tap the heat of magma several kilometres below the surface.</p><blockquote><p>地热电站利用地表以下数公里处岩浆的热量。</p></blockquote><p><strong>Speaking</strong> It&#39;s hard to imagine that the rock under our feet is, much deeper down, liquid magma.</p><blockquote><p>很难想象我们脚下的岩石，在更深处其实是液态岩浆。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>lava</td><td>熔岩</td><td>喷出地表之后的岩浆</td></tr><tr><td>molten rock</td><td>熔融岩石</td><td>描述性说法，不区分位置</td></tr><tr><td>mantle</td><td>地幔</td><td>岩浆的来源层，本身多为固态</td></tr><tr><td>melt</td><td>熔体</td><td>地质学术语，更宽泛</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>magma</em>（揉捏成团的糊状物）</li><li><strong>Family:</strong> magmatic 岩浆的 / magma chamber 岩浆房</li><li><strong>Memory Tip:</strong> 记一条界线就够：<strong>在地下叫 magma，喷出地表叫 lava</strong>。同一个东西，两个名字，按位置分。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>a magma</s> ✘；要说 a body of magma。</li><li>与 lava 严格区分，这是地理题的高频考点。</li><li>拼写 magma，不是 <s>magmar</s>。</li></ul></div><div class="vocab-card"><h2 id="thermodynamic" tabindex="-1"><a class="header-anchor" href="#thermodynamic"><span>Thermodynamic</span></a></h2><p class="vc-meta"><strong>/ˌθɜːməʊdaɪˈnæmɪk/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>热力学的；与热和能量转换有关的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>thermodynamic equilibrium</td><td>热力学平衡</td></tr><tr><td>the laws of thermodynamics</td><td>热力学定律</td></tr><tr><td>thermodynamic processes</td><td>热力学过程</td></tr><tr><td>thermodynamic efficiency</td><td>热效率</td></tr><tr><td>a thermodynamic cycle</td><td>热力循环</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram illustrates the thermodynamic cycle by which the plant converts heat into electricity.</p><blockquote><p>该图说明了该电站将热能转化为电能的热力循环。</p></blockquote><p><strong>Writing Task 2</strong> No engine can exceed the thermodynamic limits set by the temperature difference between its heat source and its surroundings.</p><blockquote><p>任何发动机都无法突破由热源与环境温差所设定的热力学极限。</p></blockquote><p><strong>Speaking</strong> Our physics teacher used a cup of coffee to explain thermodynamics — heat always flows towards the colder thing.</p><blockquote><p>物理老师用一杯咖啡讲热力学：热量总是流向更冷的一方。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>thermal</td><td>热的</td><td>只讲热，不涉及能量转换规律</td></tr><tr><td>mechanical</td><td>机械的</td><td>描述形式，不是规律</td></tr><tr><td>kinetic</td><td>动能的</td><td>只对应能量的一种形态</td></tr><tr><td>energetic</td><td>能量充沛的</td><td>日常用语，非术语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> thermo-（热）+ dynamic（动力、运动）→ &quot;热的运动规律&quot;</li><li><strong>Family:</strong> thermometer 温度计 / thermal 热的 / dynamics 动力学 / geothermal 地热的</li><li><strong>Memory Tip:</strong> thermo 热 + dynamic 动力 = 研究&quot;热怎么变成功&quot;。发电、发动机、地热，全靠这套规律。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 thermodynamics（带 s，但作单数用）。</li><li>连写成一个词，不加连字符。</li><li>拼写 thermodynamic 中间是 -dyna-，不是 <s>-dina-</s>。</li></ul></div><div class="vocab-card"><h2 id="geology" tabindex="-1"><a class="header-anchor" href="#geology"><span>Geology</span></a></h2><p class="vc-meta"><strong>/dʒiˈɒlədʒi/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>地质学</li><li>（某地区的）地质构造</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the geology of the area</td><td>该地区的地质</td></tr><tr><td>structural geology</td><td>构造地质学</td></tr><tr><td>a geological survey</td><td>地质勘查</td></tr><tr><td>geological time</td><td>地质年代</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the geology beneath the coastal plain.</p><blockquote><p>该示意图显示了沿海平原之下的地质构造。</p></blockquote><p><strong>Writing Task 2</strong> Understanding the local geology is essential before a dam can be built.</p><blockquote><p>建坝之前，了解当地的地质情况至关重要。</p></blockquote><p><strong>Speaking</strong> I took a geology course and ended up loving rocks more than I expected.</p><blockquote><p>我选了一门地质学课程，结果比预想的更喜欢岩石。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>earth science</td><td>地球科学</td><td>范围更大，含气象、海洋</td></tr><tr><td>geomorphology</td><td>地貌学</td><td>专研究地表形态</td></tr><tr><td>topography</td><td>地形</td><td>指地表起伏，非地下构造</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>geo-</em>（地球）+ <em>-logia</em>（学科）</li><li><strong>Family:</strong> geology 地质学 / geological 地质的 / geologist 地质学家 / geography 地理学</li><li><strong>Memory Tip:</strong> geo = 地球。五个 geo- 一起记：geology 地质、geography 地理、geometry 几何（原义&quot;丈量土地&quot;）、geothermal 地热、geopolitics 地缘政治。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词多为 geological：geological survey、geological time。</li><li>geology 既可指学科，也可指某地的地质构造。</li><li>与 geography 别混：一个管地下，一个管地表分布。</li></ul></div><div class="vocab-card"><h2 id="plate" tabindex="-1"><a class="header-anchor" href="#plate"><span>Plate</span></a></h2><p class="vc-meta"><strong>/pleɪt/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：盘子；板块（地质）；（金属）板；车牌</li><li>动词：镀（金属）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a tectonic plate</td><td>构造板块</td></tr><tr><td>a plate boundary</td><td>板块边界</td></tr><tr><td>a plate of</td><td>一盘</td></tr><tr><td>a licence plate</td><td>车牌</td></tr><tr><td>plated with gold</td><td>镀金的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows two tectonic plates moving apart at a mid-ocean ridge.</p><blockquote><p>该示意图显示了两个构造板块在洋中脊处相互分离。</p></blockquote><p><strong>Writing Task 2</strong> Most earthquakes occur along plate boundaries where stress accumulates.</p><blockquote><p>大多数地震发生在应力不断累积的板块边界带。</p></blockquote><p><strong>Speaking</strong> Careful, that plate&#39;s hot.</p><blockquote><p>小心，那个盘子很烫。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dish</td><td>碟</td><td>较浅，用于盛菜</td></tr><tr><td>slab</td><td>厚板</td><td>指厚重的块状材料</td></tr><tr><td>sheet</td><td>薄板</td><td>指薄而大片</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>plattus</em>（平的）→ 盘子</li><li><strong>Family:</strong> plate 盘子；板块 / plateau 高原 / platform 平台 / platter 大盘</li><li><strong>Memory Tip:</strong> 一个&quot;平&quot;字串一串：plate 盘子、plateau 高原、platform 平台、plate tectonics 板块构造。板块叫 plate，正因为它像一块大平板。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;板块&quot;是 tectonic plate；&quot;板块构造&quot;是 plate tectonics。</li><li>plate boundary（板块边界）是地质灾害话题的高频短语。</li><li>plate 作&quot;板块&quot;是地质专义，别在其他语境乱用。</li></ul></div><div class="vocab-card"><h2 id="sediment" tabindex="-1"><a class="header-anchor" href="#sediment"><span>Sediment</span></a></h2><p class="vc-meta"><strong>/ˈsedɪmənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>沉积物，沉淀物（被水、风搬运后沉积的物质）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>river sediment</td><td>河流沉积物</td></tr><tr><td>sediment transport</td><td>泥沙搬运</td></tr><tr><td>layers of sediment</td><td>沉积层</td></tr><tr><td>sediment deposits</td><td>沉积矿床</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows sediment settling on the river bed as the current slows.</p><blockquote><p>该示意图显示了水流放缓时沉积物在河床沉降的过程。</p></blockquote><p><strong>Writing Task 2</strong> Dams trap sediment that would otherwise rebuild deltas downstream.</p><blockquote><p>大坝拦住了本该用来重建下游三角洲的泥沙。</p></blockquote><p><strong>Speaking</strong> There was a layer of sediment at the bottom of the bottle.</p><blockquote><p>瓶底有一层沉淀物。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>deposit</td><td>沉积物</td><td>强调堆积的结果</td></tr><tr><td>silt</td><td>淤泥</td><td>特指细颗粒泥沙</td></tr><tr><td>residue</td><td>残留物</td><td>强调剩余的少量物质</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>sedimentum</em> ← <em>sedere</em>（坐、沉下）</li><li><strong>Family:</strong> sediment 沉积物 / sedimentary 沉积的 / sedimentation 沉积作用 / sedimentary rock 沉积岩</li><li><strong>Memory Tip:</strong> sedere = 坐。沉下来&quot;坐&quot;在水底的东西就是 sediment。sedimentary rock（沉积岩）是地理必考术语。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>一般不可数：sediment，不说 <s>a sediment</s>（除非指某一层）。</li><li>形容词是 sedimentary：sedimentary rock（沉积岩），别拼成 <s>sedimentory</s>。</li><li>别与 sentiment（情绪）混，拼写只差一个字母。</li></ul></div><div class="vocab-card"><h2 id="silt" tabindex="-1"><a class="header-anchor" href="#silt"><span>Silt</span></a></h2><p class="vc-meta"><strong>/sɪlt/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：淤泥，粉砂（细颗粒泥沙）</li><li>动词：（使）淤积，淤塞</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>silt deposits</td><td>淤泥沉积</td></tr><tr><td>silt up</td><td>淤塞</td></tr><tr><td>fertile silt</td><td>肥沃的淤泥</td></tr><tr><td>silt-laden water</td><td>含沙量高的水</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the reservoir silting up over fifty years.</p><blockquote><p>该示意图显示了水库在五十年间逐渐淤积的过程。</p></blockquote><p><strong>Writing Task 2</strong> Floods deposit fertile silt on farmland, which is why deltas are farmed so intensively.</p><blockquote><p>洪水在农田上留下肥沃淤泥，这正是三角洲农业如此集约的原因。</p></blockquote><p><strong>Speaking</strong> The harbour has silted up, so big ships can&#39;t get in any more.</p><blockquote><p>港口淤塞了，大船再也进不来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mud</td><td>泥</td><td>泛指湿软的泥土，非粒径概念</td></tr><tr><td>sediment</td><td>沉积物</td><td>范围更大，含砂砾</td></tr><tr><td>sludge</td><td>污泥</td><td>多指污水处理的泥浆</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>sylt</em>，与&quot;盐沼、泥滩&quot;的语感相关</li><li><strong>Family:</strong> silt 淤泥 / silty 淤泥质的 / siltation 淤积 / silt up 淤塞</li><li><strong>Memory Tip:</strong> silt 是水里的&quot;细泥&quot;，粒径介于砂与黏土之间。河道、水库&quot;淤塞&quot;就是 silt up；三角洲的肥沃就来自洪水带来的 silt。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>silts</s>（silt 作动词时才有第三人称单数）。</li><li>&quot;淤塞&quot;用动词短语 silt up：The lake silted up。</li><li>别与 salt（盐）混，一个字母之差。</li></ul></div><div class="vocab-card"><h2 id="muddy" tabindex="-1"><a class="header-anchor" href="#muddy"><span>Muddy</span></a></h2><p class="vc-meta"><strong>/ˈmʌdi/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：泥泞的；浑浊的；（论述）含糊不清的</li><li>动词：使浑浊，使混乱</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>muddy water</td><td>浑浊的水</td></tr><tr><td>a muddy path</td><td>泥泞的小路</td></tr><tr><td>muddy boots</td><td>沾泥的靴子</td></tr><tr><td>muddy the waters</td><td>把水搅浑；使问题复杂化</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows muddy floodwater spreading across the fields.</p><blockquote><p>照片显示了漫过田地的浑浊洪水。</p></blockquote><p><strong>Writing Task 2</strong> Muddy water blocks sunlight and suffocates aquatic plants.</p><blockquote><p>浑浊的水阻断阳光，使水生植物窒息。</p></blockquote><p><strong>Speaking</strong> My boots are muddy — I&#39;ll leave them outside.</p><blockquote><p>我靴子沾了泥，就放门外吧。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dirty</td><td>脏的</td><td>泛指有污物，不一定是泥</td></tr><tr><td>murky</td><td>浑浊的</td><td>强调不透明，多形容水</td></tr><tr><td>sludgy</td><td>泥浆般的</td><td>强调黏稠</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>mud</em>（泥）+ <em>-y</em>（充满……的），注意双写 d</li><li><strong>Family:</strong> mud 泥 / muddy 泥泞的 / mudflat 泥滩 / mudslide 泥石流</li><li><strong>Memory Tip:</strong> 两条线：水变浑（muddy water）与话变糊（muddy the waters 搅浑水）。mudslide（泥石流）是灾害话题高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写双 d：muddy，不是 <s>mudy</s>；比较级 muddier。</li><li>muddy the waters 是习语，意为&quot;使情况更复杂&quot;。</li><li>形容水用 muddy / murky，形容路用 muddy，形容人不用。</li></ul></div><div class="vocab-card"><h2 id="clay" tabindex="-1"><a class="header-anchor" href="#clay"><span>Clay</span></a></h2><p class="vc-meta"><strong>/kleɪ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>黏土（粒径极细、保水性强）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>clay soil</td><td>黏土土壤</td></tr><tr><td>a clay layer</td><td>黏土层</td></tr><tr><td>heavy clay</td><td>重黏土</td></tr><tr><td>clay pot</td><td>陶罐</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The cross-section shows a layer of clay beneath the topsoil.</p><blockquote><p>该剖面图显示了表土之下的一层黏土。</p></blockquote><p><strong>Writing Task 2</strong> Clay holds water tightly, so fields on clay stay wet long after rain.</p><blockquote><p>黏土保水性强，因此黏土地在雨后很久仍然湿漉。</p></blockquote><p><strong>Speaking</strong> The soil here is heavy clay — almost impossible to dig in summer.</p><blockquote><p>这里的土是重黏土，夏天几乎挖不动。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mud</td><td>泥</td><td>湿软的泥，非土壤质地分类</td></tr><tr><td>loam</td><td>壤土</td><td>砂、粉砂、黏土比例均衡，最宜耕作</td></tr><tr><td>silt</td><td>粉砂</td><td>粒径介于砂与黏土之间</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>clǣg</em>（黏土、泥）</li><li><strong>Family:</strong> clay 黏土 / clayey 黏质的 / clay soil 黏土 / clay pot 陶罐</li><li><strong>Memory Tip:</strong> 土壤质地三分法：sand（砂，排水快）、silt（粉砂，居中）、clay（黏土，保水强）。三者比例决定 soil texture，这是地理与农业的共同基础。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a clay</s>；说 a layer of clay。</li><li>形容词是 clayey（黏质的）。</li><li>与 loam 区分：loam 是三种颗粒的理想配比，最肥沃。</li></ul></div><div class="vocab-card"><h2 id="dirt" tabindex="-1"><a class="header-anchor" href="#dirt"><span>Dirt</span></a></h2><p class="vc-meta"><strong>/dɜːt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>污垢，脏东西</li><li>泥土，地面（dirt road）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a layer of dirt</td><td>一层污垢</td></tr><tr><td>a dirt road</td><td>土路</td></tr><tr><td>dirt cheap</td><td>非常便宜</td></tr><tr><td>dig up dirt on</td><td>挖出……的丑闻</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a dirt track leading to the village.</p><blockquote><p>照片显示一条通往村子的土路。</p></blockquote><p><strong>Writing Task 2</strong> Dust and dirt from construction sites add significantly to particulate pollution.</p><blockquote><p>建筑工地的扬尘与泥土显著加剧了颗粒物污染。</p></blockquote><p><strong>Speaking</strong> There&#39;s dirt all over the floor — take your shoes off.</p><blockquote><p>地板上全是泥，把鞋脱了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>soil</td><td>土壤</td><td>中性，指能生长植物的土</td></tr><tr><td>grime</td><td>污垢</td><td>指长期积累的油污</td></tr><tr><td>filth</td><td>污秽</td><td>语气强，含厌恶</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>drit</em>（污物、粪）</li><li><strong>Family:</strong> dirt 污垢 / dirty 脏的 / dirt road 土路 / dirt cheap 极便宜</li><li><strong>Memory Tip:</strong> dirt 是&quot;不该在那儿的脏东西&quot;，soil 是&quot;能种东西的土&quot;。两个词都译&quot;土&quot;，但褒贬和场景完全不同。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>dirts</s>。</li><li>&quot;土壤&quot;（农业、地理语境）用 soil，用 dirt 会显得不专业。</li><li>dirty 拼写单 r 加 -y，不是 <s>dirtty</s>。</li></ul></div><div class="vocab-card"><h2 id="debris" tabindex="-1"><a class="header-anchor" href="#debris"><span>Debris</span></a></h2><p class="vc-meta"><strong>/ˈdebriː/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>碎片，残骸；废墟；（地质）岩屑</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rock debris</td><td>岩石碎屑</td></tr><tr><td>a debris flow</td><td>泥石流</td></tr><tr><td>clear the debris</td><td>清理废墟</td></tr><tr><td>space debris</td><td>太空垃圾</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows debris flow paths on the slopes below the volcano.</p><blockquote><p>该地图显示了火山下方坡地上的泥石流路径。</p></blockquote><p><strong>Writing Task 2</strong> Debris from the collapsed building blocked the main road for days.</p><blockquote><p>倒塌建筑产生的残骸堵塞主干道达数日。</p></blockquote><p><strong>Speaking</strong> After the storm the beach was covered in debris.</p><blockquote><p>风暴过后海滩上满是残骸。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rubble</td><td>瓦砾</td><td>多指建筑碎石</td></tr><tr><td>wreckage</td><td>残骸</td><td>指交通工具、建筑的残余</td></tr><tr><td>fragments</td><td>碎片</td><td>泛指小碎片</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>débris</em> ← <em>briser</em>（打碎）</li><li><strong>Family:</strong> debris 碎片 / debris flow 泥石流 / debris field 残骸散落区</li><li><strong>Memory Tip:</strong> 法语&quot;被打碎的东西&quot;。发音 /ˈdebriː/，词尾的 s 不发音——这一点最容易读错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>debrises</s> 或 <s>a debris</s>。</li><li>发音 /ˈdebriː/，别读成 /dɪˈbraɪs/。</li><li>地质上 debris flow 就是&quot;泥石流&quot;，与 mudslide 近义。</li></ul></div><div class="vocab-card"><h2 id="crack" tabindex="-1"><a class="header-anchor" href="#crack"><span>Crack</span></a></h2><p class="vc-meta"><strong>/kræk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：裂缝，裂纹；爆裂声</li><li>动词：裂开；破解；严厉打击（crack down on）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a crack in the wall</td><td>墙上的裂缝</td></tr><tr><td>a hairline crack</td><td>发丝裂纹</td></tr><tr><td>crack down on</td><td>严厉打击</td></tr><tr><td>crack open</td><td>撬开</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows cracks in the ground along the fault line.</p><blockquote><p>该地图显示了沿断层线分布的地面裂缝。</p></blockquote><p><strong>Writing Task 2</strong> Drought can open deep cracks in clay soils, damaging foundations.</p><blockquote><p>干旱会在黏土中裂开深缝，损坏地基。</p></blockquote><p><strong>Speaking</strong> There&#39;s a crack in the ceiling — I hope it&#39;s not structural.</p><blockquote><p>天花板上有道裂缝，希望不是结构问题。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fissure</td><td>裂隙</td><td>地质术语，多指岩层裂开</td></tr><tr><td>crevice</td><td>窄缝</td><td>岩石间的细缝</td></tr><tr><td>split</td><td>裂口</td><td>强调被劈开</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>cracian</em>（发出爆裂声）</li><li><strong>Family:</strong> crack 裂缝 / cracked 破裂的 / crackdown 严厉打击 / cracker 饼干</li><li><strong>Memory Tip:</strong> 从&quot;爆裂声&quot;到&quot;裂缝&quot;，再到 crack down on（严打）。地质写作里要更专业就用 fissure。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 in：a crack in the wall。</li><li>crack down on 是&quot;严打&quot;，名词是 crackdown（一个词）。</li><li>hairline crack 是&quot;发丝裂纹&quot;，常指墙体细微裂缝。</li></ul></div><div class="vocab-card"><h2 id="gap" tabindex="-1"><a class="header-anchor" href="#gap"><span>Gap</span></a></h2><p class="vc-meta"><strong>/ɡæp/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>缺口，缝隙</li><li>差距，鸿沟；空白，间断</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a gap between</td><td>……之间的差距／缝隙</td></tr><tr><td>bridge the gap</td><td>弥合差距</td></tr><tr><td>the wealth gap</td><td>贫富差距</td></tr><tr><td>a gap in the market</td><td>市场空白</td></tr><tr><td>a gap year</td><td>间隔年</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a gap in the mountain chain where a pass crosses.</p><blockquote><p>该地图显示了山脉中一处供道路通行的隘口缺口。</p></blockquote><p><strong>Writing Task 2</strong> The gap between rich and poor regions has widened over the past decade.</p><blockquote><p>过去十年间，贫富地区之间的差距进一步扩大。</p></blockquote><p><strong>Speaking</strong> There&#39;s a gap in the fence where the sheep get through.</p><blockquote><p>篱笆上有个缺口，羊就从那儿钻过去。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>opening</td><td>开口</td><td>泛指，无&quot;差距&quot;义</td></tr><tr><td>breach</td><td>缺口</td><td>多指被攻破的缺口</td></tr><tr><td>disparity</td><td>差距</td><td>学术，多指不公平的差异</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺斯语 <em>gap</em>（裂口）</li><li><strong>Family:</strong> gap 缺口 / gape 张口呆看 / gappy 有缺口的</li><li><strong>Memory Tip:</strong> 两条线：物理缝隙（a gap in the fence）与抽象差距（the wealth gap）。写作里 bridge / narrow / widen the gap 三个搭配最常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>结构是 the gap between A and B。</li><li>搭配：bridge the gap（弥合）、narrow the gap（缩小）、widen the gap（扩大）。</li><li>gap year 是&quot;（升学前的）间隔年&quot;，不是&quot;空档年&quot;。</li></ul></div><div class="vocab-card"><h2 id="erode" tabindex="-1"><a class="header-anchor" href="#erode"><span>Erode</span></a></h2><p class="vc-meta"><strong>/ɪˈrəʊd/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>侵蚀，腐蚀（土地、岩石、海岸）</li><li>逐渐削弱（信心、权力、价值）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>erode the coastline</td><td>侵蚀海岸线</td></tr><tr><td>soil erosion</td><td>土壤侵蚀</td></tr><tr><td>be eroded by</td><td>被……侵蚀</td></tr><tr><td>erode confidence</td><td>削弱信心</td></tr><tr><td>wind and water erode</td><td>风与水侵蚀</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how wave action has eroded the cliff base since 1990.</p><blockquote><p>该示意图显示了自 1990 年以来海浪作用如何侵蚀崖底。</p></blockquote><p><strong>Writing Task 2</strong> Repeated flooding erodes both the land and the livelihoods of the people who farm it.</p><blockquote><p>反复的洪水既侵蚀土地，也侵蚀靠这片土地为生的人的生计。</p></blockquote><p><strong>Speaking</strong> The path has been eroded by rain — you can barely see where it used to go.</p><blockquote><p>小路被雨水冲蚀了，几乎看不出原来的走向。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>wear away</td><td>磨损</td><td>口语，强调慢慢磨掉</td></tr><tr><td>corrode</td><td>腐蚀</td><td>化学作用，多指金属</td></tr><tr><td>wash away</td><td>冲走</td><td>强调搬运走，不只是侵蚀</td></tr><tr><td>undermine</td><td>逐渐削弱</td><td>多用于抽象事物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>e-</em>（出）+ <em>rodere</em>（啃咬）→ &quot;啃掉&quot;</li><li><strong>Family:</strong> erode 侵蚀 / erosion 侵蚀（名词）/ erosive 侵蚀性的 / rodent 啮齿动物</li><li><strong>Memory Tip:</strong> rodere = 啃。同源词 rodent 就是&quot;爱啃的动物&quot;。风和水一口一口&quot;啃&quot;掉土地，就是 erosion——画面感极强。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 erosion，不是 <s>erodation</s>。</li><li>&quot;土壤侵蚀&quot;是 soil erosion（名词），不说 <s>soil erode</s>。</li><li>比喻用法 erode confidence / trust 很常用，写作里是加分项。</li></ul></div><div class="vocab-card"><h2 id="deteriorate" tabindex="-1"><a class="header-anchor" href="#deteriorate"><span>Deteriorate</span></a></h2><p class="vc-meta"><strong>/dɪˈtɪəriəreɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>恶化，变坏；（质量、健康、关系）下降</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>deteriorate rapidly</td><td>迅速恶化</td></tr><tr><td>deteriorate into</td><td>恶化为（更糟的状态）</td></tr><tr><td>health deteriorates</td><td>健康状况变差</td></tr><tr><td>conditions deteriorate</td><td>条件变差</td></tr><tr><td>a deteriorating situation</td><td>不断恶化的局势</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows that air quality deteriorated steadily between 2005 and 2015 before improving.</p><blockquote><p>该图显示空气质量在 2005 至 2015 年间持续恶化，之后才有所改善。</p></blockquote><p><strong>Writing Task 2</strong> Once coastal defences deteriorate, salt water can contaminate farmland within a single season.</p><blockquote><p>一旦海岸防护设施老化失效，海水就能在一个季度内污染农田。</p></blockquote><p><strong>Speaking</strong> My Spanish was decent at school, but it&#39;s deteriorated badly since.</p><blockquote><p>我上学时西班牙语还不错，之后退步得厉害。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>worsen</td><td>恶化</td><td>最中性，口语书面皆可</td></tr><tr><td>decline</td><td>下降，衰退</td><td>强调数量或水平下滑</td></tr><tr><td>degenerate</td><td>退化，堕落</td><td>语气更重，含&quot;变质&quot;意味</td></tr><tr><td>decay</td><td>腐烂，衰败</td><td>多用于有机物或建筑</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>deterior</em>（更坏的）+ <em>-ate</em>；<em>deterior</em> 本身即&quot;坏&quot;的比较级</li><li><strong>Family:</strong> deteriorate 恶化 / deterioration 恶化（名词）/ deteriorating 不断恶化的</li><li><strong>Memory Tip:</strong> 写作里更常用它的名词形式：the deterioration of air quality，比 getting worse and worse 高级得多。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>主要作不及物动词：conditions deteriorate；不说 <s>deteriorate the conditions</s>。</li><li>名词是 deterioration，别漏掉 -ion。</li><li>拼写 de-te-rio-rate，中间是 terior，不是 <s>teori</s>。</li></ul></div><div class="vocab-card"><h2 id="aggravate" tabindex="-1"><a class="header-anchor" href="#aggravate"><span>Aggravate</span></a></h2><p class="vc-meta"><strong>/ˈæɡrəveɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>使恶化，加重（问题、病情、局势）</li><li>（口语）惹恼，激怒</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>aggravate the problem</td><td>使问题更严重</td></tr><tr><td>aggravate the situation</td><td>使局势恶化</td></tr><tr><td>be aggravated by</td><td>因……而加剧</td></tr><tr><td>aggravating circumstances</td><td>加重情节（法律）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how deforestation aggravated soil erosion across the region.</p><blockquote><p>该图表显示了滥伐森林如何加剧了该地区的土壤侵蚀。</p></blockquote><p><strong>Writing Task 2</strong> Subsidies for fossil fuels aggravate an air pollution problem that is already severe.</p><blockquote><p>对化石燃料的补贴，使本已严重的空气污染问题进一步加剧。</p></blockquote><p><strong>Speaking</strong> Don&#39;t scratch it — you&#39;ll only aggravate the rash.</p><blockquote><p>别抓，你只会让皮疹更严重。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>exacerbate</td><td>使恶化</td><td>更正式，学术写作首选</td></tr><tr><td>worsen</td><td>使变糟</td><td>中性，及物不及物皆可</td></tr><tr><td>intensify</td><td>加剧</td><td>强调强度上升</td></tr><tr><td>irritate</td><td>刺激；惹恼</td><td>只对应&quot;惹恼&quot;或皮肤刺激</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>aggravāre</em> = <em>ad-</em>（向）+ <em>gravis</em>（重的）→ &quot;使更重&quot;</li><li><strong>Family:</strong> aggravate 加重 / aggravation 加重；烦恼 / grave 严重的；坟墓 / gravity 重力</li><li><strong>Memory Tip:</strong> gravis = 重，同族还有 gravity（重力）、grave（严重的）。把问题&quot;加重&quot;就是 aggravate。雅思写作里 exacerbate 更书面，日常搭配 aggravate 更自然。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>是及物动词，必须带宾语；<s>the situation aggravates</s> ✘，应为 the situation worsens。</li><li>口语义&quot;惹恼&quot;（He aggravates me）不宜出现在正式写作中。</li><li>与 aggregate（总计）拼写易混，注意 -grav- 与 -greg-。</li></ul></div><div class="vocab-card"><h2 id="degrade" tabindex="-1"><a class="header-anchor" href="#degrade"><span>Degrade</span></a></h2><p class="vc-meta"><strong>/dɪˈɡreɪd/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>使（环境、土地、质量）退化，降低</li><li>使丢脸，贬低；使降级</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>degrade the environment</td><td>使环境退化</td></tr><tr><td>degraded land</td><td>退化的土地</td></tr><tr><td>degrade in quality</td><td>质量下降</td></tr><tr><td>environmental degradation</td><td>环境退化</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The maps show how overgrazing has degraded the grassland over thirty years.</p><blockquote><p>这组地图显示了三十年过度放牧如何使草原退化。</p></blockquote><p><strong>Writing Task 2</strong> Plastics degrade extremely slowly, and only a small fraction is ever recycled.</p><blockquote><p>塑料降解极其缓慢，而其中只有一小部分被回收。</p></blockquote><p><strong>Speaking</strong> The video quality degrades badly once you upload it at that resolution.</p><blockquote><p>用那个分辨率上传之后，视频画质会明显下降。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>deteriorate</td><td>恶化</td><td>不及物，强调状态变坏</td></tr><tr><td>downgrade</td><td>降级</td><td>指等级、评级下调</td></tr><tr><td>debase</td><td>贬低</td><td>多指价值、品质被拉低</td></tr><tr><td>erode</td><td>侵蚀</td><td>强调被外力一点点磨掉</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>de-</em>（向下）+ <em>gradus</em>（步、等级）→ &quot;往下走一级&quot;</li><li><strong>Family:</strong> degrade 使退化 / degradation 退化；降解 / grade 等级 / upgrade 升级 / downgrade 降级</li><li><strong>Memory Tip:</strong> gradus = 台阶。de-（下）+ grade（台阶）= 下台阶。同族三个方向一起记：upgrade 上、downgrade 下、degrade 往下且带&quot;受损&quot;意味。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>环境&quot;退化&quot;作名词用 environmental degradation，不用 <s>environmental degrade</s>。</li><li>可生物降解是 biodegradable，不是 <s>bio-degraded</s>。</li><li>用于人时含&quot;羞辱&quot;意味，别在正式文本里随意使用。</li></ul></div><div class="vocab-card"><h2 id="upgrade" tabindex="-1"><a class="header-anchor" href="#upgrade"><span>Upgrade</span></a></h2><p class="vc-meta"><strong>/ˌʌpˈɡreɪd/</strong> · verb · 动词（名词读 /ˈʌpɡreɪd/）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>升级，提高（设备、服务、等级、设施）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>upgrade the system</td><td>升级系统</td></tr><tr><td>upgrade to</td><td>升级到</td></tr><tr><td>a free upgrade</td><td>免费升舱／升级</td></tr><tr><td>upgrade the road network</td><td>升级路网</td></tr><tr><td>a software upgrade</td><td>软件升级</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The maps show that the road was upgraded from two lanes to four between 2000 and 2010.</p><blockquote><p>这组地图显示该道路在 2000 至 2010 年间由两车道升级为四车道。</p></blockquote><p><strong>Writing Task 2</strong> Rather than build new power stations, the city upgraded its grid to handle renewable input.</p><blockquote><p>该市没有新建电站，而是升级电网以接纳可再生能源。</p></blockquote><p><strong>Speaking</strong> My flight was overbooked, so they upgraded me to business class.</p><blockquote><p>我的航班超售了，于是他们把我升到了商务舱。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>improve</td><td>改善</td><td>泛指变好，不含&quot;等级&quot;义</td></tr><tr><td>modernise</td><td>现代化</td><td>强调更新换代</td></tr><tr><td>renovate</td><td>翻新</td><td>多指建筑修缮</td></tr><tr><td>update</td><td>更新</td><td>偏信息、软件版本</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>up</em>（向上）+ <em>grade</em>（等级、台阶）</li><li><strong>Family:</strong> upgrade 升级 / downgrade 降级 / grade 等级 / gradual 逐渐的</li><li><strong>Memory Tip:</strong> 反义成对：upgrade ↔ downgrade。重音是英式考点——动词在后 /ˌʌpˈɡreɪd/，名词在前 /ˈʌpɡreɪd/。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词重音在后、名词重音在前，读错很扎耳。</li><li>&quot;把 A 升级为 B&quot;用 upgrade A to B，不加 <s>up</s>。</li><li>名词可数：a major upgrade / several upgrades。</li></ul></div><div class="vocab-card"><h2 id="border" tabindex="-1"><a class="header-anchor" href="#border"><span>Border</span></a></h2><p class="vc-meta"><strong>/ˈbɔːdə(r)/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：边界，国界；边缘（地带）</li><li>动词：与……接壤；接近于</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the border between</td><td>……之间的边界</td></tr><tr><td>cross the border</td><td>越过边界</td></tr><tr><td>a border region</td><td>边境地区</td></tr><tr><td>border on</td><td>与……接壤；近乎</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the river forming the border between the two countries.</p><blockquote><p>该地图显示这条河构成了两国的边界。</p></blockquote><p><strong>Writing Task 2</strong> Wildlife does not respect national borders, so conservation requires international cooperation.</p><blockquote><p>野生动物不受国界限制，因此保护工作需要国际合作。</p></blockquote><p><strong>Speaking</strong> We crossed the border at night — it took two hours.</p><blockquote><p>我们夜里过的边境，花了两个小时。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>boundary</td><td>界限</td><td>更抽象，可指任何分界</td></tr><tr><td>frontier</td><td>边疆</td><td>带&quot;待开发边缘&quot;意味</td></tr><tr><td>borderline</td><td>边界线</td><td>也指&quot;临界状态&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>bordure</em> ← <em>bord</em>（边缘）</li><li><strong>Family:</strong> border 边界 / borderline 边界线；临界的 / border on 近乎 / bordello（同源异义）</li><li><strong>Memory Tip:</strong> border 是具体的&quot;线或带&quot;，boundary 更抽象（如学科界限），frontier 带&quot;边疆、未开发&quot;的历史感。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;与……接壤&quot;用 border on 或 border with。</li><li>&quot;边界&quot;说 the border between A and B。</li><li>borderline 是形容词&quot;临界的&quot;：a borderline case。</li></ul></div><div class="vocab-card"><h2 id="margin" tabindex="-1"><a class="header-anchor" href="#margin"><span>Margin</span></a></h2><p class="vc-meta"><strong>/ˈmɑːdʒɪn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>边缘，边沿（水域、地区的边）</li><li>页边空白</li><li>差额；利润率；余地</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>by a narrow margin</td><td>以微弱差距</td></tr><tr><td>profit margin</td><td>利润率</td></tr><tr><td>margin of error</td><td>误差范围</td></tr><tr><td>the margin of the lake</td><td>湖的边缘</td></tr><tr><td>leave a margin</td><td>留出余地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the profit margin falling from 12% to 5% over five years.</p><blockquote><p>该图表显示了五年间利润率从 12% 降到 5%。</p></blockquote><p><strong>Writing Task 2</strong> The bill passed by a narrow margin, leaving the policy contested.</p><blockquote><p>该法案以微弱优势通过，政策仍存争议。</p></blockquote><p><strong>Speaking</strong> Leave a margin at the side of the page for corrections.</p><blockquote><p>页边留点空，方便改。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>edge</td><td>边缘</td><td>最通用，指外沿</td></tr><tr><td>fringe</td><td>外缘</td><td>强调边缘地带，非界线</td></tr><tr><td>leeway</td><td>余地</td><td>只对应抽象&quot;回旋空间&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>margo</em>（边缘）</li><li><strong>Family:</strong> margin 边缘；差额 / marginal 边缘的；微小的 / marginalise 使边缘化</li><li><strong>Memory Tip:</strong> 三义一条线：页边 → 差额（by a narrow margin）→ 余地（margin of error）。marginal 又引申出&quot;微不足道的&quot;&quot;被边缘化的&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 by：won by a narrow margin。</li><li>marginal 常表&quot;微小的&quot;：a marginal increase。</li><li>profit margin 是&quot;利润率&quot;，不是&quot;利润&quot;。</li></ul></div><div class="vocab-card"><h2 id="fringe" tabindex="-1"><a class="header-anchor" href="#fringe"><span>Fringe</span></a></h2><p class="vc-meta"><strong>/frɪndʒ/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：边缘，外围；（头发的）刘海</li><li>形容词：边缘的，非主流的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>on the fringe of</td><td>在……的边缘</td></tr><tr><td>the fringes of society</td><td>社会边缘</td></tr><tr><td>fringe benefits</td><td>附加福利</td></tr><tr><td>a fringe of trees</td><td>一排树构成的边缘</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows wetlands on the northern fringe of the city.</p><blockquote><p>该地图显示了城市北缘的湿地。</p></blockquote><p><strong>Writing Task 2</strong> People living on the fringes of cities often lack basic services.</p><blockquote><p>居住在城市边缘的人常常缺乏基本公共服务。</p></blockquote><p><strong>Speaking</strong> There&#39;s a fringe of pine trees around the field.</p><blockquote><p>田地四周有一圈松树。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>edge</td><td>边缘</td><td>指外沿线，最中性</td></tr><tr><td>periphery</td><td>外围</td><td>学术，强调与中心对立</td></tr><tr><td>margin</td><td>边沿</td><td>也指页边、差额</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>fimbria</em>（流苏）→ 古法语 <em>frenge</em></li><li><strong>Family:</strong> fringe 边缘；刘海 / fringed 有流苏的 / fringe benefits 附加福利</li><li><strong>Memory Tip:</strong> 原义是&quot;流苏&quot;——垂在边上的穗子，所以指&quot;外缘&quot;。the fringes of society 是社会边缘；fringe benefits 是工资之外的附加福利。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 on：on the fringe(s) of。</li><li>作形容词表&quot;非主流的&quot;：fringe theatre。</li><li>别与 flange（法兰、凸缘）混，拼写接近但不同。</li></ul></div><div class="vocab-card"><h2 id="terrain" tabindex="-1"><a class="header-anchor" href="#terrain"><span>Terrain</span></a></h2><p class="vc-meta"><strong>/təˈreɪn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>地形，地势；（某一地区的）地面特征</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rugged terrain</td><td>崎岖的地形</td></tr><tr><td>flat terrain</td><td>平坦的地形</td></tr><tr><td>mountainous terrain</td><td>山地地形</td></tr><tr><td>difficult terrain</td><td>难以通行的地带</td></tr><tr><td>the terrain of</td><td>……的地形</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the terrain changes from coastal plain to steep upland within only ten kilometres.</p><blockquote><p>该地图显示了地形如何在仅十公里的范围内从沿海平原变为陡峭高地。</p></blockquote><p><strong>Writing Task 2</strong> In mountainous terrain, road building is costly because every kilometre requires cuttings and tunnels.</p><blockquote><p>在山地地形中修路成本很高，因为每一公里都需要开挖路堑和隧道。</p></blockquote><p><strong>Speaking</strong> The terrain was rougher than we expected, so we walked the last five kilometres.</p><blockquote><p>地形比我们预想的崎岖，最后五公里我们是走过去的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>topography</td><td>地形（学）</td><td>更学术，指高低起伏的整体格局</td></tr><tr><td>landform</td><td>地貌</td><td>指单个地貌类型，如河谷、沙丘</td></tr><tr><td>relief</td><td>地势起伏</td><td>地图学术语，强调高低差</td></tr><tr><td>ground</td><td>地面</td><td>泛指，不含形态特征</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>terrain</em> ← 拉丁 <em>terrenum</em>（土地）← <em>terra</em>（土地）</li><li><strong>Family:</strong> terrain 地形 / territory 领土 / terrestrial 陆地的 / terrace 梯田</li><li><strong>Memory Tip:</strong> terra = 土地，terrain 就是&quot;这块地长什么样&quot;。地图题里 the terrain is flat / undulating / steep 比 the land is flat 更专业。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>terrains</s>（只在指多片不同区域时偶见）。</li><li>与 landscape 区分：terrain 强调起伏与可通行性，landscape 强调视觉景观。</li><li>拼写 -rain，不是 <s>-rane</s>。</li></ul></div><div class="vocab-card"><h2 id="landscape" tabindex="-1"><a class="header-anchor" href="#landscape"><span>Landscape</span></a></h2><p class="vc-meta"><strong>/ˈlændskeɪp/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：（陆上）风景，景观；地貌；（某领域的）局面、格局</li><li>动词：对……做景观美化</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a rural landscape</td><td>乡村景观</td></tr><tr><td>a dramatic landscape</td><td>壮观的景观</td></tr><tr><td>landscape architecture</td><td>景观设计</td></tr><tr><td>dominate the landscape</td><td>在景观中占据主导</td></tr><tr><td>the landscape of</td><td>……的景观／格局</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The two maps show how the landscape has been transformed by mining over the past fifty years.</p><blockquote><p>这两幅地图显示了采矿在过去五十年间如何改变了这一带的景观。</p></blockquote><p><strong>Writing Task 2</strong> Wind farms have become a familiar feature of the rural landscape, though not everyone welcomes them.</p><blockquote><p>风电场已成为乡村景观中常见的景象，尽管并非所有人都欢迎它们。</p></blockquote><p><strong>Speaking</strong> The landscape here is completely different from where I grew up — no hills at all.</p><blockquote><p>这里的景观和我长大的地方完全不同，一座山都没有。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>scenery</td><td>风景</td><td>多指自然美景，不可数，旅游语境</td></tr><tr><td>view</td><td>景色</td><td>从某一视点看到的景</td></tr><tr><td>terrain</td><td>地形</td><td>强调起伏与通行条件</td></tr><tr><td>panorama</td><td>全景</td><td>视野开阔的连续景观</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 荷兰语 <em>landschap</em>（地区、景致）= land + -scape（形状、状态）</li><li><strong>Family:</strong> landscape 景观 / landscaping 景观绿化 / landscape architect 景观设计师 / seascape 海景</li><li><strong>Memory Tip:</strong> -scape 是&quot;看起来的样子&quot;，一套记：landscape 陆景 / seascape 海景 / cityscape 城景 / moonscape 月面般荒地。抽象用法也高频：the political landscape 政治格局。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a landscape / landscapes；说&quot;景色美&quot;要带冠词 a beautiful landscape。</li><li>与 terrain 别混：能否通车说 terrain，好不好看说 landscape。</li><li>动词义只用于园林绿化，不用来泛指&quot;改造&quot;。</li></ul></div><div class="vocab-card"><h2 id="continent" tabindex="-1"><a class="header-anchor" href="#continent"><span>Continent</span></a></h2><p class="vc-meta"><strong>/ˈkɒntɪnənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大陆，洲</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the African continent</td><td>非洲大陆</td></tr><tr><td>across the continent</td><td>横跨大陆</td></tr><tr><td>continental climate</td><td>大陆性气候</td></tr><tr><td>on the Continent</td><td>在欧洲大陆（英式特指）</td></tr><tr><td>the Asian continent</td><td>亚洲大陆</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the area of each continent with its share of the world&#39;s population.</p><blockquote><p>该图表比较了各大洲的面积与其在世界人口中所占的比例。</p></blockquote><p><strong>Writing Task 2</strong> Australia is the only continent where a single country occupies the entire landmass.</p><blockquote><p>澳大利亚是唯一一个由单一国家占据整块陆地的洲。</p></blockquote><p><strong>Speaking</strong> I&#39;ve never set foot on the African continent, but it&#39;s top of my list.</p><blockquote><p>我从未踏上过非洲大陆，但那是我最想去的地方。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mainland</td><td>大陆本土</td><td>相对岛屿而言</td></tr><tr><td>landmass</td><td>陆块</td><td>地理学术语，强调连续陆地</td></tr><tr><td>supercontinent</td><td>超大陆</td><td>如盘古大陆</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>continens</em>（连成一片的）← <em>continere</em>（连在一起）= con-（一起）+ ten-（握持）</li><li><strong>Family:</strong> continent 大陆 / continental 大陆的 / contain 包含 / continuous 连续的</li><li><strong>Memory Tip:</strong> con + tin（握）+ ent = &quot;连在一起的一大块&quot;。continent 另有&quot;自制的&quot;形容词义（罕用），别与 continuous 混。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>大洲名必须大写：Africa、Asia、Antarctica。</li><li>&quot;在非洲&quot;说 in Africa，不说 <s>on the Africa continent</s>。</li><li>英式 on the Continent 特指欧洲大陆，不是&quot;在某个洲&quot;。</li></ul></div><div class="vocab-card"><h2 id="cave" tabindex="-1"><a class="header-anchor" href="#cave"><span>Cave</span></a></h2><p class="vc-meta"><strong>/keɪv/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：洞穴，山洞</li><li>动词：塌陷（cave in）；（在压力下）让步</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a limestone cave</td><td>石灰岩洞</td></tr><tr><td>cave entrance</td><td>洞口</td></tr><tr><td>explore a cave</td><td>探洞</td></tr><tr><td>cave paintings</td><td>洞穴壁画</td></tr><tr><td>cave in</td><td>塌陷；让步</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how water dissolves limestone to form a cave system over thousands of years.</p><blockquote><p>该示意图显示了水如何在数千年间溶解石灰岩，形成洞穴系统。</p></blockquote><p><strong>Writing Task 2</strong> Cave paintings provide some of the earliest evidence of human symbolic thought.</p><blockquote><p>洞穴壁画提供了人类象征性思维最早的证据之一。</p></blockquote><p><strong>Speaking</strong> We went into a cave near the coast — it was cool and completely dark inside.</p><blockquote><p>我们进了海岸边的一个洞穴，里面阴凉，一片漆黑。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cavern</td><td>大岩洞</td><td>规模大，多用于旅游宣传</td></tr><tr><td>grotto</td><td>石窟</td><td>小而精致，常带水池</td></tr><tr><td>hollow</td><td>凹处</td><td>泛指，不一定是洞</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>cavus</em>（空的）</li><li><strong>Family:</strong> cave 洞穴 / cavern 大洞穴 / cavity 腔 / excavate 挖掘 / concave 凹的</li><li><strong>Memory Tip:</strong> cavus = 空的，cave 就是&quot;被挖空的地方&quot;。cave in 由&quot;塌进去&quot;引申为&quot;顶不住压力而妥协&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>cave in 是动词短语，名词写作 a cave-in（带连字符）。</li><li>不说 <s>a cave of water</s>，要说 a cave full of water。</li><li>与 hole 区分：cave 是人能进入的大空腔。</li></ul></div><div class="vocab-card"><h2 id="cliff" tabindex="-1"><a class="header-anchor" href="#cliff"><span>Cliff</span></a></h2><p class="vc-meta"><strong>/klɪf/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>悬崖，峭壁</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a sheer cliff</td><td>陡直的悬崖</td></tr><tr><td>cliff face</td><td>崖壁</td></tr><tr><td>cliff edge</td><td>崖边</td></tr><tr><td>chalk cliffs</td><td>白垩崖</td></tr><tr><td>fall off a cliff</td><td>从悬崖坠落；（数据）骤降</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a narrow path running along the top of a chalk cliff.</p><blockquote><p>这张照片显示一条小径沿着白垩悬崖的顶部延伸。</p></blockquote><p><strong>Writing Task 2</strong> Coastal cliffs retreat inland as waves undercut their base, a process known as cliff erosion.</p><blockquote><p>随着海浪掏蚀崖底，海岸悬崖不断向内陆后退，这一过程称为崖壁侵蚀。</p></blockquote><p><strong>Speaking</strong> Don&#39;t go too close to the cliff edge — the wind is really strong up there.</p><blockquote><p>别太靠近崖边，上面风特别大。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>precipice</td><td>绝壁</td><td>更书面，强调险峻</td></tr><tr><td>bluff</td><td>陡崖</td><td>美式，多指河岸或海滨</td></tr><tr><td>escarpment</td><td>断层崖</td><td>地质学，长条状陡坡</td></tr><tr><td>crag</td><td>岩崖</td><td>小而崎岖的岩石突出</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>clif</em>（崖），与德语 <em>Klippe</em> 同源</li><li><strong>Family:</strong> cliff 悬崖 / cliffy 多悬崖的 / cliffhanger 悬念 / cliffside 崖侧</li><li><strong>Memory Tip:</strong> cliffhanger 原指连载小说把主角&quot;挂在悬崖上&quot;收尾，所以是&quot;悬念&quot;。复数直接加 s：cliffs。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 cliffs，不是 <s>clives</s>。</li><li>&quot;在崖顶&quot;用 on the cliff top，不用 <s>in</s>。</li><li>别与 coral reef（珊瑚礁）拼写混。</li></ul></div><div class="vocab-card"><h2 id="glacier" tabindex="-1"><a class="header-anchor" href="#glacier"><span>Glacier</span></a></h2><p class="vc-meta"><strong>/ˈɡlæsiə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>冰川</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a melting glacier</td><td>消融的冰川</td></tr><tr><td>glacier retreat</td><td>冰川退缩</td></tr><tr><td>glacial lake</td><td>冰川湖</td></tr><tr><td>glacial period</td><td>冰期</td></tr><tr><td>the glacier flows</td><td>冰川向下流动</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the glacier has retreated roughly two kilometres since 1980.</p><blockquote><p>该地图显示自 1980 年以来冰川已退缩约两公里。</p></blockquote><p><strong>Writing Task 2</strong> Meltwater from glaciers supplies rivers that support hundreds of millions of people.</p><blockquote><p>冰川融水补给着养育数亿人口的河流。</p></blockquote><p><strong>Speaking</strong> We hiked to the foot of the glacier — the ice looked blue, not white.</p><blockquote><p>我们徒步走到冰川脚下，那冰看着是蓝的，不是白的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>ice sheet</td><td>冰盖</td><td>覆盖大片陆地的冰体</td></tr><tr><td>ice cap</td><td>冰帽</td><td>规模较小，覆盖山顶或岛屿</td></tr><tr><td>iceberg</td><td>冰山</td><td>崩落并漂在海上的冰块</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>glace</em>（冰）← 拉丁 <em>glacies</em>（冰）；形容词为 glacial</li><li><strong>Family:</strong> glacier 冰川 / glacial 冰川的；极冷的 / glaciation 冰川作用</li><li><strong>Memory Tip:</strong> glaci- = 冰。glacier 是&quot;会流动的冰河&quot;；glacial 既可指冰川，也可形容&quot;冷得像冰&quot;：a glacial stare 冷冰冰的目光。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式读 /ˈɡlæsiə(r)/，别读成 /ˈɡleɪ-/。</li><li>&quot;冰川湖&quot;是 glacial lake，不用 <s>glacier lake</s>。</li><li>与 iceberg 区分：glacier 在陆地上，iceberg 是崩落漂在海上的。</li></ul></div><div class="vocab-card"><h2 id="swamp" tabindex="-1"><a class="header-anchor" href="#swamp"><span>Swamp</span></a></h2><p class="vc-meta"><strong>/swɒmp/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：沼泽，湿地</li><li>动词：淹没；使应接不暇</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mangrove swamp</td><td>红树林沼泽</td></tr><tr><td>swampy land</td><td>沼泽地</td></tr><tr><td>drain a swamp</td><td>排干沼泽</td></tr><tr><td>tropical swamps</td><td>热带沼泽</td></tr><tr><td>be swamped with</td><td>被……淹没；忙于应付</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows that the swamp east of the river has been drained for farmland.</p><blockquote><p>该地图显示河流以东的沼泽已被排干改为农田。</p></blockquote><p><strong>Writing Task 2</strong> Swamps store carbon and buffer floods, yet they are still widely regarded as wasteland.</p><blockquote><p>沼泽储存碳并缓冲洪水，却仍被广泛视为荒地。</p></blockquote><p><strong>Speaking</strong> Our boots got stuck in the swamp, and we had to pull each other out.</p><blockquote><p>我们的靴子陷进沼泽里，只好互相把对方拉出来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>marsh</td><td>沼泽</td><td>以草本植物为主，水浅</td></tr><tr><td>bog</td><td>泥炭沼</td><td>酸性，有泥炭堆积</td></tr><tr><td>wetland</td><td>湿地</td><td>中性学术词，涵盖各类</td></tr><tr><td>fen</td><td>碱沼</td><td>碱性，多芦苇</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 可能借自荷兰语 <em>zwamp</em>（沼泽），与 sump（污水坑）同源</li><li><strong>Family:</strong> swamp 沼泽 / swampy 沼泽般的 / swampland 沼泽地 / be swamped 忙不过来</li><li><strong>Memory Tip:</strong> 按&quot;植物 + 水质&quot;分：marsh（草）／bog（泥炭、酸）／fen（碱、芦苇）／swamp（树木、常年水淹）。学术写作里 wetland 最安全。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a swamp / swamps。</li><li>be swamped with work 是&quot;忙得不可开交&quot;，与&quot;被水淹&quot;无关。</li><li>与 marsh 混用不影响理解，但正式写作优先 wetland。</li></ul></div><div class="vocab-card"><h2 id="delta" tabindex="-1"><a class="header-anchor" href="#delta"><span>Delta</span></a></h2><p class="vc-meta"><strong>/ˈdeltə/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>三角洲；希腊字母 Δ</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a river delta</td><td>河口三角洲</td></tr><tr><td>the Nile Delta</td><td>尼罗河三角洲</td></tr><tr><td>delta region</td><td>三角洲地区</td></tr><tr><td>a delta forms</td><td>三角洲形成</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows sediment accumulating at the river mouth to form a delta.</p><blockquote><p>该示意图显示了沉积物在河口堆积、逐步形成三角洲的过程。</p></blockquote><p><strong>Writing Task 2</strong> Deltas are densely populated because their soils are fertile, but they are also sinking as sea levels rise.</p><blockquote><p>三角洲人口稠密，因为土壤肥沃；但随着海平面上升，它们也在下沉。</p></blockquote><p><strong>Speaking</strong> The boat took us through the delta, and the water was full of birds.</p><blockquote><p>船带我们穿过三角洲，水面上到处是鸟。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>estuary</td><td>河口湾</td><td>喇叭形溺谷，非堆积而成</td></tr><tr><td>river mouth</td><td>河口</td><td>中性泛称</td></tr><tr><td>alluvial plain</td><td>冲积平原</td><td>范围更大，成因相同</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊字母 Δ（delta），因三角洲外形像三角形而得名</li><li><strong>Family:</strong> delta 三角洲 / deltaic 三角洲的 / deltoid 三角形的</li><li><strong>Memory Tip:</strong> 先有字母 Δ，后有地理义。estuary 是&quot;被海水淹进来的河口&quot;，delta 是&quot;泥沙堆出来的河口&quot;，成因正好相反。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>地名首字母大写：the Ganges Delta。</li><li>与 estuary 区分：一是堆积成因，一是沉溺成因。</li><li>不用 <s>delta area</s>，直接说 the delta。</li></ul></div>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};